 const [showTemplates,setShowTemplates]=useState(false),[deleteId,setDeleteId]=useState(''),[showAdvanced,setShowAdvanced]=useState(false),[showHelp,setShowHelp]=useState(false),[mobileMenu,setMobileMenu]=useState(false),[source,setSource]=useState('');
