 const [designPrompt,setDesignPrompt]=useState('A warm, grounded narrator with a natural British accent. Conversational, thoughtful, with a little texture.'),[designText,setDesignText]=useState('Some stories stay with you long after the last word.'),[designCount,setDesignCount]=useState(2),[candidates,setCandidates]=useState<{id:string;audio_base64:string;duration_ms:number;sample_rate:number}[]>([]);
