 async function design(){if(!key){setConnection(true);return;}if(!designPrompt.trim()){setError('Describe the voice you want to hear.');return;}const signal=runStart('Designing voice candidates');try{const data:any=await(await api('v1/voice-design',{method:'POST',model:'voice-design-1',body:JSON.stringify({instruction:designPrompt,reference_text:designText||undefined,n:designCount}),signal})).json();if(!data.candidates?.length)throw new Error('No voice candidates were returned. Try a different direction.');setCandidates(data.candidates);}catch(e){fail(e);}finally{setBusy('');}}
